    d(T, "bpa", "Bénéfice par action (BPA / EPS)", "Earnings per share (EPS)", 1,
      "Résultat net divisé par le nombre d'actions : la part de bénéfice qui revient à chaque action. Le BPA dilué tient compte des actions qui pourraient être créées (options, convertibles). C'est le chiffre publié et comparé au consensus.",
      "Net income divided by the number of shares: the profit attributable to each share. Diluted EPS accounts for shares that could be created (options, convertibles). It is the figure published and compared with consensus.",
      formula=r"BPA = \frac{\text{résultat net}}{N_{\text{actions}}}", see="price_earnings surprise_resultats", alias="EPS"),
